#include "noe.hpp"
#include <filesystem>
#include <iostream>
#include <string>
#include <vector>

namespace noe { int runProductionDoctor(const std::filesystem::path& root){struct Check{std::filesystem::path path;std::string label;};const std::vector<Check> required={{"README.md","public README"},{"LICENSE","MIT license"},{"LEGAL.md","legal notice"},{"SECURITY.md","security policy"},{"CONTRIBUTING.md","contribution guide"},{"CHANGELOG.md","change log"},{"project.ric","Ric project manifest"},{"ric.lock","Ric lock file"},{"Doc/_static/ric-logo.svg","Ric wolf/code logo"},{"Include/ric/ric.hpp","public bootstrap header"},{"Grammar/ric.grammar.md","grammar contract"},{"InternalDocs/CPYTHON_STRUCTURE.md","repository architecture study"},{"compiler/bootstrap/main.cpp","CLI entry point"},{"compiler/bootstrap/lexer.cpp","lexer implementation"},{"compiler/bootstrap/parser.cpp","parser implementation"},{"compiler/bootstrap/type_checker.cpp","type checker implementation"},{"compiler/bootstrap/nir.cpp","NIR implementation"},{"compiler/bootstrap/native_backend.cpp","native backend"},{"compiler/bootstrap/linker.cpp","linker driver"},{"Lib/std/core.ric","standard library core"},{"Parser/README.md","parser ownership"},{"Objects/README.md","object model"},{"Modules/README.md","module boundary"},{"Runtime/README.md","runtime architecture"},{"PCbuild/README.md","Windows build notes"},{"Mac/README.md","macOS build notes"},{"Android/README.md","Android target notes"},{"Tools/README.md","developer tools"},{"editors/vscode/package.json","VS Code language package"},{"site/index.html","public site"},{"scripts/build.sh","POSIX build script"},{"scripts/build.ps1","Windows build script"},{"examples/hello.ric","smoke example"},{"tests/arithmetic.ric","test program"}};int failures=0;std::cout<<"Ric production-track doctor\ncompiler="<<RIC_COMPILER_VERSION<<"\nlanguage="<<RIC_LANGUAGE_VERSION<<"\ntarget="<<RIC_SUPPORTED_TARGET<<"\n";for(const auto&check:required){auto full=root/check.path;if(std::filesystem::exists(full))std::cout<<"ok   "<<check.label<<" ("<<check.path.string()<<")\n";else{++failures;std::cerr<<"fail "<<check.label<<" missing: "<<full.string()<<"\n";}}const std::vector<std::filesystem::path> forbidden={root/"project.noe",root/"noe.lock",root/"include/noe",root/"grammar/noe.grammar.md"};for(const auto&path:forbidden)if(std::filesystem::exists(path)){++failures;std::cerr<<"fail legacy public Noe path present: "<<path.string()<<"\n";}if(failures==0){std::cout<<"Ric production-track repository checks passed for the supported 1.0 subset.\n";return 0;}std::cerr<<"Ric production-track repository checks failed: "<<failures<<" issue(s).\n";return 1;} }
